// Report the failure to Convex so it shows up in the app's admin view,
// not only in n8n's execution list.
const crypto = require('crypto');
const e = $input.first().json;
const report = {
  executionId: String(e.execution?.id ?? `no-id-${Date.now()}`),
  workflow: e.workflow?.name ?? 'unknown workflow',
  message: e.execution?.error?.message ?? 'unknown error',
};
console.error(`[lendloop] ${report.workflow} failed: ${report.message}`);
const body = JSON.stringify(report);
const ts = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', $env.LENDLOOP_CONVEX_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { url: `${$env.LENDLOOP_CONVEX_SITE_URL}/automation/workflow-error`, body, ts, signature } }];
